const scoreForOneSphinx = (monsterTypes: number): number =>
  monsterTypes > BONUS_TYPE_THRESHOLD
    ? 1 + POINTS_PER_BONUS_TYPE * (monsterTypes - BONUS_TYPE_THRESHOLD)
    : BASE_SPHINX_SCORE;

const countSphinxes = (army: Card[]): number => army.filter(isSphinx).length;

export const scoreArmy = (army: Card[]): number =>
  countSphinxes(army) * scoreForOneSphinx(countMonsterTypes(army));
